  // No releer decisiones válidas ni repetir llamadas con consumo incierto.
  // La IA corrige una salida técnicamente defectuosa; no hay otro intérprete.
  const recoverable=new Set(['bad_first','citas_no_corresponden_al_original',
   'articulo_sin_evidencia_verificable','evidencias_superpuestas',
   'esquema_invalido','campos_inseguros']);
